import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Grid,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import { PlayArrow as PlayArrowIcon } from '@mui/icons-material';
import { Link as RouterLink } from 'react-router-dom';
import type { Document as EvidenceDocument } from '../services/documentService';
import { HIDE_ISO_14067_UI } from '../constants/uiVisibility';
import {
  aggregateUploadedDocumentsForAssessment,
  countDocumentsWithCo2SignalsIncludingProvisional,
  countPendingVerificationDocuments,
  countProcessedDocumentsIncludingProvisional,
  type DocumentAssessmentAggregate,
} from '../utils/documentAssessmentAggregation';

const formatLabel = (value?: string) => {
  if (!value) return '—';
  return value
    .replace(/_/g, ' ')
    .replace(/\b\w/g, (char) => char.toUpperCase());
};

interface DocumentBasedCarbonAssessmentProps {
  documents: EvidenceDocument[];
  organizationName?: string;
  showCarbonAssessmentLink?: boolean;
}

const DocumentBasedCarbonAssessment: React.FC<DocumentBasedCarbonAssessmentProps> = ({
  documents,
  organizationName = 'Your organization',
  showCarbonAssessmentLink = true,
}) => {
  const [documentAssessment, setDocumentAssessment] = useState<DocumentAssessmentAggregate | null>(null);
  const [assessmentError, setAssessmentError] = useState<string | null>(null);
  const [isRunning, setIsRunning] = useState(false);

  const processedDocCount = useMemo(() => countProcessedDocumentsIncludingProvisional(documents), [documents]);
  const docSignalsCount = useMemo(() => countDocumentsWithCo2SignalsIncludingProvisional(documents), [documents]);
  const pendingVerificationDocCount = useMemo(() => countPendingVerificationDocuments(documents), [documents]);

  const runAssessment = useCallback((docs: EvidenceDocument[]) => {
    const aggregate = aggregateUploadedDocumentsForAssessment(docs, organizationName);
    if (!aggregate) {
      setDocumentAssessment(null);
      setAssessmentError(
        'No processed documents with carbon signals were found. Upload documents and wait for processing to finish.'
      );
      return;
    }
    setAssessmentError(null);
    setDocumentAssessment(aggregate);
  }, [organizationName]);

  const handleStartAssessment = useCallback(() => {
    setIsRunning(true);
    try {
      runAssessment(documents);
    } finally {
      setIsRunning(false);
    }
  }, [documents, runAssessment]);

  useEffect(() => {
    if (processedDocCount === 0) {
      setDocumentAssessment(null);
      return;
    }
    runAssessment(documents);
  }, [documents, processedDocCount, runAssessment]);

  return (
    <Card id="document-based-carbon-assessment" variant="outlined" sx={{ mb: 3 }}>
      <CardContent>
        <Typography variant="h6" gutterBottom>
          Document-based carbon assessment
        </Typography>
        <Typography variant="body2" color="text.secondary" paragraph>
          Analyze uploaded evidence to derive hotspots and organizational totals aligned with ISO 14064
          {!HIDE_ISO_14067_UI && ', manufactured product-level allocations for ISO 14067 reporting,'}
          {' '}alongside Scope 1 / 2 / 3 splits consistent with the GHG Protocol when per-document scope data is missing.
        </Typography>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 2, alignItems: 'center', mb: 2 }}>
          <Button
            variant="contained"
            size="large"
            startIcon={<PlayArrowIcon />}
            onClick={handleStartAssessment}
            disabled={isRunning}
          >
            START ASSESSMENT
          </Button>
          <Typography variant="body2" color="text.secondary">
            {isRunning
              ? 'Refreshing document inventory…'
              : `${docSignalsCount} document(s) with CO₂ signals · ${processedDocCount} processed with a carbon total`}
          </Typography>
          {pendingVerificationDocCount > 0 && (
            <Chip
              size="small"
              color="info"
              variant="outlined"
              label={`${pendingVerificationDocCount} pending bill verification`}
            />
          )}
          {showCarbonAssessmentLink ? (
            <Button component={RouterLink} to="/carbon-footprint?section=start-assessment" size="small">
              Open carbon assessment
            </Button>
          ) : null}
        </Box>
        {assessmentError && (
          <Alert
            severity={documentAssessment ? 'warning' : 'info'}
            sx={{ mb: 2 }}
            onClose={() => setAssessmentError(null)}
          >
            {assessmentError}
          </Alert>
        )}
        {documentAssessment?.includesProvisionalDocuments && (
          <Alert severity="info" sx={{ mb: 2 }}>
            {documentAssessment.provisionalDocumentCount} document
            {documentAssessment.provisionalDocumentCount === 1 ? '' : 's'} contribute provisional inventory (
            {documentAssessment.verifiedDocumentCount} confirmed). Verify bill fields to confirm these emissions
            for statutory reporting.
          </Alert>
        )}
        {documentAssessment && (
          <Grid container spacing={2}>
            <Grid item xs={12} md={4}>
              <Paper variant="outlined" sx={{ p: 2 }}>
                <Typography variant="body2" color="text.secondary">
                  Document inventory (not the Home company ledger)
                </Typography>
                <Typography variant="h5">{documentAssessment.totalCo2.toFixed(2)} kg CO₂e</Typography>
                <Typography variant="caption" color="text.secondary">
                  Based on {documentAssessment.documentCount} document(s)
                  {documentAssessment.includesProvisionalDocuments
                    ? ` · ${documentAssessment.provisionalDocumentCount} provisional`
                    : ''}
                </Typography>
              </Paper>
            </Grid>
            <Grid item xs={12} md={8}>
              <Paper variant="outlined" sx={{ p: 2 }}>
                <Typography variant="subtitle2" gutterBottom>
                  Scopes (1, 2, 3) — GHG Protocol / ISO 14064 framing
                </Typography>
                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
                  <Chip label={`Scope 1: ${documentAssessment.scope1.toFixed(1)} kg`} color="error" variant="outlined" />
                  <Chip label={`Scope 2: ${documentAssessment.scope2.toFixed(1)} kg`} color="warning" variant="outlined" />
                  <Chip label={`Scope 3: ${documentAssessment.scope3.toFixed(1)} kg`} color="info" variant="outlined" />
                </Box>
              </Paper>
            </Grid>
            <Grid item xs={12} md={6}>
              <Typography variant="subtitle1" sx={{ fontWeight: 600, mb: 1 }}>
                Hotspots (highest emitting documents)
              </Typography>
              <TableContainer component={Paper} variant="outlined">
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Document</TableCell>
                      <TableCell>Category</TableCell>
                      <TableCell align="right">kg CO₂</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {documentAssessment.hotspots.length === 0 ? (
                      <TableRow>
                        <TableCell colSpan={3}>
                          <Typography variant="body2" color="text.secondary">
                            No hotspots to display.
                          </Typography>
                        </TableCell>
                      </TableRow>
                    ) : (
                      documentAssessment.hotspots.map((h) => (
                        <TableRow key={h.id}>
                          <TableCell>
                            <Typography variant="body2" noWrap title={h.name}>
                              {h.name}
                            </Typography>
                            <Typography variant="caption" color="text.secondary">
                              {h.vendor}
                            </Typography>
                          </TableCell>
                          <TableCell>{formatLabel(h.category)}</TableCell>
                          <TableCell align="right">{h.co2.toFixed(2)}</TableCell>
                        </TableRow>
                      ))
                    )}
                  </TableBody>
                </Table>
              </TableContainer>
            </Grid>
            <Grid item xs={12} md={6}>
              <Typography variant="subtitle1" sx={{ fontWeight: 600, mb: 1 }}>
                Company-wise emissions
              </Typography>
              <TableContainer component={Paper} variant="outlined">
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Entity</TableCell>
                      <TableCell align="right">kg CO₂</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {documentAssessment.companyRows.map((row) => (
                      <TableRow key={row.label}>
                        <TableCell>{row.label}</TableCell>
                        <TableCell align="right">{row.totalKg.toFixed(2)}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            </Grid>
            {!HIDE_ISO_14067_UI && (
              <Grid item xs={12}>
                <Typography variant="subtitle1" sx={{ fontWeight: 600, mb: 1 }}>
                  Product-wise emissions (products manufactured by your company, ISO 14067)
                </Typography>
                {documentAssessment.productRows.length === 0 ? (
                  <Typography variant="body2" color="text.secondary">
                    No adequate product activity details were found on processed documents. Upload richer supporting
                    documents to improve manufactured product-level splits.
                  </Typography>
                ) : (
                  <TableContainer component={Paper} variant="outlined">
                    <Table size="small">
                      <TableHead>
                        <TableRow>
                          <TableCell>Product / line</TableCell>
                          <TableCell align="right">Quantity</TableCell>
                          <TableCell>Unit</TableCell>
                          <TableCell align="right">Allocated kg CO₂</TableCell>
                        </TableRow>
                      </TableHead>
                      <TableBody>
                        {documentAssessment.productRows.map((row) => (
                          <TableRow key={row.productName}>
                            <TableCell>{row.productName}</TableCell>
                            <TableCell align="right">{row.quantity.toFixed(2)}</TableCell>
                            <TableCell>{row.unit}</TableCell>
                            <TableCell align="right">{row.allocatedKg.toFixed(2)}</TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </TableContainer>
                )}
              </Grid>
            )}
          </Grid>
        )}
      </CardContent>
    </Card>
  );
};

export default DocumentBasedCarbonAssessment;
