/**
 * What to ask for when a row is still an estimate or miscellaneous calculation.
 * Web copy of shared/missingCarbonInputs.js. Keep the two files in sync.
 */
import { isEstimateOrMiscellaneousTransaction } from './estimateScreeningPolicy';

const ACTIVITY_GAP_IDS = new Set([
  'flight_requires_origin_destination',
  'cat4_requires_tonne_km',
  'cat9_requires_tonne_km',
  'cat6_requires_room_nights',
  'cat7_wfh_requires_hours_or_kwh',
  'bus_requires_passenger_km',
  'electricity_requires_bill_quantity',
  'electricity_quantity_amount_mismatch'
]);

const activityAsk = (unit, quantityLabel, helper, extras = {}) => ({
  unit,
  quantityLabel,
  unitOptions: extras.unitOptions || [unit],
  helper,
  requireMaterialName: extras.requireMaterialName === true,
  requireAirports: extras.requireAirports === true
});

const spendAsk = (kind, metadataField, label, helper) => ({
  kind,
  metadataField,
  label,
  helper
});

const textOf = (transaction = {}) => [
  transaction.category,
  transaction.subcategory,
  transaction.description,
  transaction.carbonFootprint?.factorLineage?.id
].join(' ').toLowerCase();

const hasActivityGap = (transaction = {}) => {
  const footprint = transaction.carbonFootprint || {};
  const ids = [
    footprint.scope3ActivityGap,
    footprint.factorLineage && footprint.factorLineage.id,
    ...(Array.isArray(footprint.complianceFlags) ? footprint.complianceFlags : [])
  ];
  return ids.some((id) => ACTIVITY_GAP_IDS.has(String(id || '')));
};

export const resolveMissingCarbonInput = (transaction = {}) => {
  if (!isEstimateOrMiscellaneousTransaction(transaction).match && !hasActivityGap(transaction)) {
    return null;
  }

  const category = String(transaction.category || '').toLowerCase();
  const factorId = String(transaction.carbonFootprint?.factorLineage?.id || '');
  const text = textOf(transaction);

  if (/\b(flight|airline|air ticket)\b/.test(text)) {
    return {
      title: 'Add the flight route from the bill',
      activity: activityAsk(
        'passenger',
        'Passengers',
        'Upload the ticket and enter the origin and destination airport codes. Kilometres alone stay at 0.',
        { unitOptions: ['passenger'], requireAirports: true }
      ),
      spend: null
    };
  }

  if (/\b(hotel|lodging|accommodation)\b/.test(text)) {
    return {
      title: 'Add hotel nights from the bill',
      activity: activityAsk(
        'night',
        'Room-nights',
        'Enter room-nights from the hotel bill. No India hotel factor is published, so the inventory stays 0 kg.'
      ),
      spend: null
    };
  }

  if (/\b(work from home|wfh|remote work|homeworking)\b/.test(text)) {
    return {
      title: 'Add home-working electricity from the bill',
      activity: activityAsk(
        'kWh',
        'kWh',
        'Enter kWh from the bill. That uses the CEA grid factor and enters the inventory. Hours alone stay at 0.',
        { unitOptions: ['kWh', 'hour'] }
      ),
      spend: null
    };
  }

  const miscellaneous = factorId === 'spend_generic' || category === 'other';

  if (miscellaneous) {
    return {
      title: 'Add the activity this purchase covers',
      activity: activityAsk(
        'kg',
        'Quantity',
        'Name the material or activity and enter its quantity. That replaces the miscellaneous factor with an activity-based calculation.',
        {
          unitOptions: ['kg', 'kWh', 'L', 'tonne-km', 'service_unit'],
          requireMaterialName: true
        }
      ),
      spend: null
    };
  }

  if (
    category === 'water'
    || ['water_consumption', 'sewage_disposal', 'wastewater_treatment'].includes(factorId)
  ) {
    return {
      title: 'Add water activity or a water unit price',
      activity: activityAsk(
        'L',
        'Litres',
        'Enter litres for an activity-based calculation.'
      ),
      spend: spendAsk(
        'water',
        'waterUnitPriceInr',
        '₹ per litre',
        'Enter the bill ₹ per litre for a spend-based calculation.'
      )
    };
  }

  if (category === 'maintenance' || factorId === 'maintenance_service_unit') {
    return {
      title: 'Add maintenance jobs or a job rate',
      activity: activityAsk(
        'service_unit',
        'Jobs or visits',
        'Enter the number of jobs. Unit service_unit, visit, or job is an activity-based calculation.',
        { unitOptions: ['service_unit', 'visit', 'job'] }
      ),
      spend: spendAsk(
        'maintenance',
        'maintenanceUnitPriceInr',
        '₹ per service unit',
        'Enter the ₹ cost of one job for a spend-based calculation.'
      )
    };
  }

  if (category === 'waste_management') {
    return {
      title: 'Add waste mass or a waste unit price',
      activity: activityAsk('kg', 'Kilograms', 'Enter kilograms for an activity-based calculation.'),
      spend: spendAsk(
        'waste',
        'wasteUnitCostInr',
        '₹ per kg',
        'Enter ₹ per kg for a spend-based calculation.'
      )
    };
  }

  if (category === 'equipment') {
    return {
      title: 'Add equipment mass',
      activity: activityAsk('kg', 'Kilograms', 'Enter kilograms for an activity-based calculation.'),
      spend: null
    };
  }

  if (category === 'telecom') {
    return {
      title: 'Add data use',
      activity: activityAsk('GB', 'Gigabytes', 'Enter gigabytes for an activity-based calculation.'),
      spend: null
    };
  }

  if (category === 'transportation' || category === 'travel') {
    if (/\b(courier|parcel|dtdc|bluedart|delhivery)\b/.test(text)) {
      return {
        title: 'Add parcel weight',
        activity: activityAsk('kg', 'Kilograms', 'Enter parcel kilograms for an activity-based calculation.'),
        spend: null
      };
    }
    if (/\bbus\b/.test(text)) {
      return {
        title: 'Add passenger-kilometres from the bill',
        activity: activityAsk(
          'passenger-km',
          'Passenger-kilometres',
          'The bus factor is per passenger-km. Upload the bill and enter passenger-kilometres. Vehicle kilometres stay at 0.'
        ),
        spend: null
      };
    }
    if (/\b(cab|taxi|rail|commut|passenger)\b/.test(text)) {
      return {
        title: 'Add distance from the bill',
        activity: activityAsk(
          'km',
          'Kilometres',
          'Enter kilometres from the bill for an activity-based calculation.',
          { unitOptions: ['km', 'passenger-km'] }
        ),
        spend: null
      };
    }
    return {
      title: 'Add freight activity',
      activity: activityAsk(
        'tonne-km',
        'Tonne-kilometres',
        'Enter tonne-km for an activity-based calculation. A rupee amount is not a freight factor.'
      ),
      spend: null
    };
  }

  if (category === 'raw_materials') {
    return {
      title: 'Add material mass',
      activity: activityAsk(
        'kg',
        'Kilograms',
        'Enter kilograms for an activity-based calculation.',
        { requireMaterialName: factorId === 'spend_generic' }
      ),
      spend: null
    };
  }

  const flags = Array.isArray(transaction.carbonFootprint?.complianceFlags)
    ? transaction.carbonFootprint.complianceFlags.map((flag) => String(flag))
    : [];
  if (flags.includes('electricity_quantity_amount_mismatch')) {
    return {
      title: 'Electricity quantity does not match the amount',
      activity: activityAsk(
        'kWh',
        'kWh',
        'The electricity quantity does not match the rupee amount. Upload the electricity bill so the quantity and unit can be verified before carbon is calculated.'
      ),
      spend: null
    };
  }

  const fuel = /\b(diesel|petrol|lpg|cng|fuel|coal|natural gas|furnace)\b/.test(text)
    || factorId.startsWith('fuel_');
  if (category === 'energy' || category === 'utilities' || fuel) {
    if (fuel && !/\b(kwh|electricity|discom|power bill)\b/.test(text)) {
      return {
        title: 'Add fuel quantity or a fuel unit price',
        activity: activityAsk(
          'L',
          'Litres',
          'Enter litres for an activity-based calculation.',
          { unitOptions: ['L', 'kg', 'm3'] }
        ),
        spend: spendAsk(
          'fuel',
          'fuelUnitPriceInr',
          '₹ per litre',
          'Enter ₹ per litre for a spend-based calculation.'
        )
      };
    }
    return {
      title: 'Upload the electricity bill',
      activity: activityAsk(
        'kWh',
        'kWh',
        'Upload the electricity bill and enter the metered quantity and unit (kWh). A rupee amount is not used to estimate kilowatt-hours.'
      ),
      spend: null
    };
  }

  return {
    title: 'Add the missing activity',
    activity: activityAsk(
      'kg',
      'Quantity',
      'Enter a quantity and unit for an activity-based calculation.',
      { unitOptions: ['kg', 'kWh', 'L', 'tonne-km', 'service_unit'] }
    ),
    spend: null
  };
};
